3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useRef, useState } from "react";
6	import { NxLogo } from "./Logo";
7	import { ClaudeMark } from "./ClaudeMark";
8	import {
9	  IconServer,
10	  IconGame,
11	  IconSpark,
12	  IconDisk,
