21	/**
22	 * Marketing top nav (v2 redesign). A grouped structure instead of a flat link
23	 * list: a Products mega-menu organized by outcome (Compute / Storage & Network /
24	 * Web Essentials) plus a "by use case" rail, then Pricing · Compare · Blog and a
25	 * Company dropdown. One prominent primary CTA; a live Status pill on the right.
26	 */
27	
28	type Item = { label: string; href: string; desc: string; icon: (p: { size?: number }) => React.ReactNode; badge?: string };
29	
30	const PRODUCT_GROUPS: { title: string; items: Item[] }[] = [
31	  {
32	    title: "Compute",
33	    items: [
34	      { label: "VPS Hosting", href: "/vps", desc: "Full-root NVMe KVM servers", icon: IconServer },
35	      { label: "Game Servers", href: "/game-servers", desc: "Minecraft, Rust, Valheim & more", icon: IconGame },
36	      { label: "Claude AI Builder", href: "/features", desc: "Build your server in plain English", icon: ClaudeMark, badge: "New" },
37	      { label: "Matrix", href: "/matrix", desc: "Build several apps at once with AI", icon: IconApps, badge: "New" },
38	    ],
39	  },
40	  {
41	    title: "Storage & Network",
42	    items: [
43	      { label: "Block Storage", href: "/block-storage", desc: "Add-on NVMe volumes", icon: IconDisk },
44	      { label: "NxCloud", href: "/nxcloud", desc: "Your own managed Nextcloud", icon: IconDisk, badge: "New" },
45	      { label: "Dedicated IPv4", href: "/vps", desc: "A clean, static IP per server", icon: IconNetwork },
46	    ],
47	  },
48	  {
49	    title: "Web Essentials",
50	    items: [
51	      { label: "Web Hosting", href: "/web-hosting", desc: "One-click WordPress & sites", icon: IconApps, badge: "New" },
52	      { label: "Domains", href: "/domains", desc: "Register & manage domains", icon: IconGlobe },
53	      { label: "Business Email", href: "/business-email", desc: "Mailboxes on your own domain", icon: IconMail },
54	    ],
55	  },
56	];
57	
58	const USE_CASES: Item[] = [
59	  { label: "Vibe coding", href: "/vibe-coding", desc: "Build sites & apps, no code", icon: IconSpark, badge: "New" },
60	  { label: "Free tools", href: "/tools", desc: "WHOIS, DNS, SSL & more", icon: IconNetwork, badge: "Free" },
61	  { label: "Migrate to Nxeon", href: "/migrate", desc: "Free — bring your servers", icon: IconArrow },
62	  { label: "Developers & API", href: "/developers", desc: "Automate everything", icon: IconCode },
63	  { label: "AI apps & agents", href: "/features", desc: "Ship agents in minutes", icon: IconSpark },
64	];
65	
66	const COMPANY: { label: string; href: string }[] = [
67	  { label: "About", href: "/about" },
68	  { label: "Security", href: "/security" },
69	  { label: "Contact", href: "/contact" },
70	  { label: "Affiliate program", href: "/affiliate" },
71	  { label: "Status", href: "/status" },
72	];
