74	export function MarketingHeader() {
75	  const pathname = usePathname();
76	  const [open, setOpen] = useState(false); // mobile drawer
77	  const [menu, setMenu] = useState<null | "products" | "company">(null); // desktop dropdown
78	  const [scrolled, setScrolled] = useState(false);
79	  const [authed, setAuthed] = useState(false);
80	  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
81	
82	  // Show "Back to portal" for a signed-in visitor while keeping marketing pages
83	  // static. Two-step, after mount: (1) optimistic read of the non-httpOnly
84	  // `nxeon_authed` flag cookie (instant, no flash when present), then (2) an
85	  // authoritative probe to /api/auth/status which reads the real session cookie
86	  // server-side — so it's correct even if the flag cookie is missing or stale.
87	  useEffect(() => {
88	    setAuthed(document.cookie.split("; ").some((c) => c.startsWith("nxeon_authed=")));
89	    let alive = true;
90	    fetch("/api/auth/status", { cache: "no-store" })
91	      .then((r) => (r.ok ? r.json() : null))
92	      .then((d) => {
93	        if (alive && d && typeof d.authed === "boolean") setAuthed(d.authed);
94	      })
95	      .catch(() => {});
96	    return () => {
97	      alive = false;
98	    };
99	  }, []);
100	
101	  useEffect(() => {
102	    const onScroll = () => setScrolled(window.scrollY > 8);
103	    onScroll();
104	    window.addEventListener("scroll", onScroll, { passive: true });
105	    return () => window.removeEventListener("scroll", onScroll);
106	  }, []);
107	
108	  useEffect(() => {
109	    setOpen(false);
110	    setMenu(null);
111	  }, [pathname]);
112	
113	  // Hover-intent: brief close delay so diagonal mouse travel to the panel doesn't drop it.
114	  const openMenu = (m: "products" | "company") => {
115	    if (closeTimer.current) clearTimeout(closeTimer.current);
116	    setMenu(m);
117	  };
118	  const scheduleClose = () => {
119	    if (closeTimer.current) clearTimeout(closeTimer.current);
120	    closeTimer.current = setTimeout(() => setMenu(null), 120);
121	  };
122	
123	  return (
124	    <header
125	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
126	        scrolled || menu ? "border-white/[0.06] bg-navy-950/85 backdrop-blur-xl" : "border-transparent bg-transparent"
127	      }`}
128	      onMouseLeave={scheduleClose}
129	    >
130	      <div className="rail flex h-[72px] items-center justify-between">
131	        <Link href="/" aria-label="Nxeon home" className="shrink-0">
132	          <NxLogo id="hdr" size={44} />
133	        </Link>
134	
135	        {/* Desktop nav */}
136	        <nav className="hidden items-center gap-1 lg:flex">
137	          <button
138	            className={`nav-trigger nav-underline ${menu === "products" ? "is-open" : ""}`}
139	            onMouseEnter={() => openMenu("products")}
140	            onFocus={() => openMenu("products")}
141	            aria-expanded={menu === "products"}
142	          >
143	            Products <Chevron open={menu === "products"} />
144	          </button>
145	          <TopLink href="/matrix" pathname={pathname}>Matrix</TopLink>
146	          <TopLink href="/pricing" pathname={pathname}>Pricing</TopLink>
147	          <TopLink href="/compare" pathname={pathname}>Compare</TopLink>
148	          <TopLink href="/blog" pathname={pathname}>Blog</TopLink>
149	          <button
150	            className={`nav-trigger nav-underline ${menu === "company" ? "is-open" : ""}`}
151	            onMouseEnter={() => openMenu("company")}
152	            onFocus={() => openMenu("company")}
153	            aria-expanded={menu === "company"}
154	          >
155	            Company <Chevron open={menu === "company"} />
156	          </button>
157	        </nav>
158	
159	        <div className="hidden items-center gap-2 lg:flex">
160	          <Link href="/status" className="flex items-center gap-1.5 rounded-full border border-white/[0.07] px-2.5 py-1 text-xs text-slate-400 transition-colors hover:text-white">
161	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
162	            Status
163	          </Link>
164	          {authed ? (
165	            <>
166	              <Link href="/dashboard/settings" className="btn-ghost">My account</Link>
167	              <Link href="/dashboard" className="btn-primary">Back to portal</Link>
168	            </>
169	          ) : (
170	            <>
171	              <Link href="/login" className="btn-ghost">Log in</Link>
172	              <Link href="/register" className="btn-primary">Get started</Link>
173	            </>
174	          )}
175	        </div>
176	
177	        <button
178	          className="btn-ghost rounded-lg p-2 lg:hidden"
179	          aria-label="Toggle menu"
180	          aria-expanded={open}
181	          onClick={() => setOpen((v) => !v)}
182	        >
183	          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
184	            {open ? <path d="M6 6l12 12M18 6 6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
185	          </svg>
186	        </button>
187	      </div>
188	
189	      {/* Desktop mega-menu panels */}
190	      {menu === "products" && (
191	        <div
192	          className="absolute inset-x-0 top-full hidden lg:block"
193	          onMouseEnter={() => openMenu("products")}
194	          onMouseLeave={scheduleClose}
195	        >
196	          <div className="rail pb-6">
197	            <div className="grid grid-cols-[1.1fr_1.1fr_1.1fr_0.9fr] gap-2 rounded-2xl border border-white/10 bg-navy-950/95 p-3 shadow-2xl backdrop-blur-2xl">
198	              {PRODUCT_GROUPS.map((g) => (
199	                <div key={g.title} className="p-2">
200	                  <p className="section-label mb-2 px-2">{g.title}</p>
201	                  <div className="space-y-0.5">
202	                    {g.items.map((it) => (
203	                      <MegaItem key={it.label} item={it} />
204	                    ))}
205	                  </div>
206	                </div>
207	              ))}
208	              <div className="rounded-xl bg-white/[0.02] p-2">
209	                <p className="section-label mb-2 px-2">By use case</p>
210	                <div className="space-y-0.5">
211	                  {USE_CASES.map((it) => (
212	                    <MegaItem key={it.label} item={it} />
213	                  ))}
214	                </div>
215	                <div className="mx-2 my-2 border-t border-white/[0.06]" />
216	                <Link href="/features" className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-brand-300 hover:bg-white/[0.04]">
217	                  All features <IconArrow size={15} />
218	                </Link>
219	              </div>
220	            </div>
221	          </div>
222	        </div>
223	      )}
224	
225	      {menu === "company" && (
226	        <div
227	          className="absolute inset-x-0 top-full hidden lg:block"
228	          onMouseEnter={() => openMenu("company")}
229	          onMouseLeave={scheduleClose}
230	        >
231	          <div className="rail flex justify-end pb-6">
232	            <div className="w-56 rounded-2xl border border-white/10 bg-navy-950/95 p-2 shadow-2xl backdrop-blur-2xl">
233	              {COMPANY.map((l) => (
234	                <Link key={l.href} href={l.href} className="flex items-center justify-between rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
235	                  {l.label}
236	                  {l.label === "Status" && <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />}
237	                </Link>
238	              ))}
239	            </div>
240	          </div>
241	        </div>
242	      )}
243	
244	      {/* Mobile drawer */}
245	      {open && (
246	        <div className="border-t border-white/[0.06] bg-navy-950/95 backdrop-blur-xl lg:hidden">
247	          <nav className="rail flex max-h-[70vh] flex-col gap-1 overflow-y-auto py-4">
248	            {PRODUCT_GROUPS.map((g) => (
249	              <div key={g.title} className="mb-1">
250	                <p className="section-label px-3 pb-1 pt-2">{g.title}</p>
251	                {g.items.map((it) => (
252	                  <Link key={it.label} href={it.href} className="flex items-center gap-3 rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white">
253	                    <span className="text-brand-300">{it.icon({ size: 18 })}</span>
254	                    {it.label}
255	                    {it.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{it.badge}</span>}
256	                  </Link>
257	                ))}
258	              </div>
259	            ))}
260	            <div className="my-1 border-t border-white/[0.06]" />
261	            {[{ label: "Pricing", href: "/pricing" }, { label: "Compare", href: "/compare" }, { label: "Blog", href: "/blog" }, ...COMPANY].map((l) => (
262	              <Link key={l.href} href={l.href} className="rounded-lg px-3 py-2.5 text-sm font-medium text-slate-300 hover:bg-white/[0.05] hover:text-white">
263	                {l.label}
264	              </Link>
265	            ))}
266	            <div className="mt-2 flex flex-col gap-2 border-t border-white/[0.06] pt-3">
267	              {authed ? (
268	                <>
269	                  <Link href="/dashboard/settings" className="btn-secondary w-full">My account</Link>
270	                  <Link href="/dashboard" className="btn-primary w-full">Back to portal</Link>
271	                </>
272	              ) : (
273	                <>
274	                  <Link href="/login" className="btn-secondary w-full">Log in</Link>
275	                  <Link href="/register" className="btn-primary w-full">Get started</Link>
276	                </>
277	              )}
278	            </div>
279	          </nav>
280	        </div>
281	      )}
282	    </header>
283	  );
284	}
285	
286	function TopLink({ href, pathname, children }: { href: string; pathname: string; children: React.ReactNode }) {
287	  const active = pathname === href;
288	  return (
289	    <Link href={href} className={`nav-underline rounded-lg px-3 py-2 text-sm font-medium transition-colors ${active ? "is-open text-white" : "text-slate-400 hover:text-white"}`}>
290	      {children}
291	    </Link>
292	  );
293	}
294	
295	function MegaItem({ item }: { item: Item }) {
296	  return (
297	    <Link href={item.href} className="group flex items-start gap-3 rounded-xl px-2 py-2 transition-colors hover:bg-white/[0.05]">
298	      <span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-white/[0.06] bg-white/[0.03] text-brand-300 transition-colors group-hover:border-brand-500/30 group-hover:text-brand-200">
299	        {item.icon({ size: 17 })}
300	      </span>
301	      <span className="min-w-0">
302	        <span className="flex items-center gap-1.5 text-sm font-medium text-slate-100">
303	          {item.label}
304	          {item.badge && <span className="rounded-full bg-brand-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-brand-200">{item.badge}</span>}
305	        </span>
306	        <span className="block truncate text-xs text-slate-500">{item.desc}</span>
307	      </span>
308	    </Link>
309	  );
310	}
311	
312	function Chevron({ open }: { open: boolean }) {
313	  return (
314	    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" className={`transition-transform duration-200 ${open ? "rotate-180" : ""}`}>
315	      <path d="m6 9 6 6 6-6" />
316	    </svg>
317	  );
318	}
